import hashlib,json,os,stat,sys
from pathlib import Path
expected=set("redis_observer_native_once.py test_redis_observer_native_once.py redis_observer_admission.py test_redis_observer_admission.py redis_observer_probe.py REDIS-TEMPORARY-OBSERVER-PREPARED.md REDIS-NATIVE-RUN-TEMPLATE.json".split())
try:
    if len(sys.argv)!=4: raise ValueError()
    stage,manifest=Path(sys.argv[1]),Path(sys.argv[2])
    raw=manifest.read_bytes()
    if hashlib.sha256(raw).hexdigest()!=sys.argv[3]: raise ValueError()
    pins=json.loads(raw)
    meta=stage.lstat()
    if not stat.S_ISDIR(meta.st_mode) or stat.S_IMODE(meta.st_mode)!=0o700 or meta.st_uid!=os.getuid(): raise ValueError()
    if set(pins)!=expected or {p.name for p in stage.iterdir()}!=expected: raise ValueError()
    for name in sorted(expected):
        path=stage/name
        meta=path.lstat()
        if not stat.S_ISREG(meta.st_mode) or meta.st_nlink!=1 or meta.st_uid!=os.getuid(): raise ValueError()
        if hashlib.sha256(path.read_bytes()).hexdigest()!=pins[name]: raise ValueError()
except Exception:
    print("STAGE_REJECTED")
    raise SystemExit(1) from None
print("STAGE_VERIFIED")
